/* Governed Promotion Packets: printed candidate assessment and supervisor review. */
let promotionPackets={schemaVersion:'promotion-packets-1',templates:[],packets:[],audit:[]};

async function loadPromotionPackets(){
  try{
    const res=await SuiteBridge.send('suite:loadModuleData',{}, {module:'promotion-packets'});
    recordModuleLoadInfo('promotion-packets',res);
    const value=typeof res.data==='string'?JSON.parse(res.data||'{}'):(res.data||{});
    if(!Array.isArray(value.templates)||!Array.isArray(value.packets)||!Array.isArray(value.audit))throw new Error('Packet arrays are missing.');
    promotionPackets=value;
    if(typeof promotionDigitalResetDrafts==='function')promotionDigitalResetDrafts();
  }catch(e){
    moduleLoadInfo['promotion-packets']={...(moduleLoadInfo['promotion-packets']||{}),writeAllowed:false};
    toast('Promotion Packets load failed: '+e.message);
  }
}
function promotionPacket(id){return (promotionPackets.packets||[]).find(p=>p.id===id)}
function promotionLocalDate(value){const date=new Date(value||'');return Number.isNaN(date.getTime())?'':date.toLocaleDateString()}
function promotionEmployee(id){return (roster.employees||[]).find(e=>String(e.id)===String(id))}
function promotionPacketCan(action){return hasCapability(action==='issue'||action==='scenario'||action==='delete'||action==='restore'||action==='import'?'promotion.manage':action==='review'||action==='assessment'?'promotion.review':'promotion.decide')}
function promotionCommand(action,fields){
 const snapshot=JSON.parse(JSON.stringify(fields||{}));
 return coordinateModuleSave('promotion-packets',()=>dispatchPromotionCommand(action,snapshot)).catch(e=>{toast(e.message);return null});
}
async function dispatchPromotionCommand(action,fields){
  if(!promotionPacketCan(action)){toast('Promotion packet permission is required.');return null}
  const info=moduleLoadInfo['promotion-packets']||{};
  if(info.writeAllowed===false||info.conflict){toast('Promotion Packets is read-only. Reload the latest data or review Data Health.');return null}
  try{
    const res=await SuiteBridge.send('suite:promotionPacketCommand',{action,...fields,expectedRevision:info.revision||''},{authorization:authorizationEnvelope()});
    promotionPackets=JSON.parse(res.data);
    updateModuleRevisionAfterSave('promotion-packets',res.save);
    closeModal();
    safeRenderPages({preserveScroll:true});
    toast('Promotion packet '+action+' saved.');
    return res;
  }catch(e){
    if(isStaleWriteConflictError(e)){
      moduleLoadInfo['promotion-packets']={...info,conflict:true,conflictMessage:e.message};
      showDataConflictModal('promotion-packets',e.message);
    }else{if(String(e.message||e).includes('OUTCOME_UNKNOWN'))moduleLoadInfo['promotion-packets']={...info,writeAllowed:false};toast('Promotion packet save failed: '+e.message);}
    return null;
  }
}
function renderPromotionPackets(){
  if(window._promotionDigitalOpen)return renderPromotionDigitalPacket(window._promotionDigitalOpen);
  const all=[...(promotionPackets.packets||[])].sort((a,b)=>String(b.issuedAt).localeCompare(String(a.issuedAt)));
  const focus=String(window._promotionEmployeeFocus||'');
  const q=String(window._promotionSearch||'').toLowerCase();
  const showDeleted=window._promotionShowDeleted===true;
  const visible=all.filter(p=>showDeleted?p.status==='Deleted':p.status!=='Deleted');
  const rows=visible.filter(p=>(!focus||String(p.employeeId)===focus)&&(!q||((p.employee?.name||'')+' '+(p.employee?.eid||'')+' '+p.tier+' '+p.status).toLowerCase().includes(q)));
  const pending=all.filter(p=>p.status==='Reviewed').length;
  const canIssue=promotionPacketCan('issue');
  return `<div class="page-head"><div><div class="page-title">Promotion Packets</div><div class="page-sub">Export a supervisor packet that opens offline, or work in the Suite. The Security Manager imports the evaluation and makes the final decision.</div></div><div class="top-actions">${canIssue?'<button class="primary" onclick="openPromotionIssueModal()">+ Issue Packet</button><button onclick="openPromotionBank()">Manage Scenario Banks</button><button onclick="document.getElementById(\'promotionPortableImportFile\').click()">Import Supervisor Evaluation</button><input id="promotionPortableImportFile" type="file" accept=".json,application/json" class="hidden" onchange="importPromotionPortableEvaluation(this)">':''}<button onclick="printPromotionRegister()">Print Register</button><button onclick="exportPromotionRegister()">Export CSV</button></div></div>
    ${renderPeopleWorkflowNav('promotion-packets')}
    <div class="notice">Issue creates a packet with six randomly selected scenarios from its level's bank. Manager deletion hides a packet and preserves an audit record. Reprinting uses those same questions. A packet recommendation does not change rank, pay, or HR approval.</div>
    <div class="grid cols-3"><div class="kpi"><div class="num">${all.filter(p=>p.status!=='Deleted').length}</div><div class="lbl">Active Packets</div></div><div class="kpi"><div class="num">${all.filter(p=>p.status==='Issued').length}</div><div class="lbl">With Supervisor</div></div><div class="kpi"><div class="num">${pending}</div><div class="lbl">Awaiting Manager</div></div></div>
    <div class="card"><div class="card-title">Packet Register</div><div class="training-filters"><div><label>Search</label><input value="${esc(window._promotionSearch||'')}" placeholder="Employee, ID, level or status" oninput="window._promotionSearch=this.value;safeRenderPages()"></div>${canAdmin()?'<div><label>Register view</label><button onclick="window._promotionShowDeleted=!window._promotionShowDeleted;safeRenderPages()">'+(showDeleted?'Show active packets':'Show deleted packets')+'</button></div>':''}${focus?'<div><label>Employee</label><button onclick="window._promotionEmployeeFocus=\'\';safeRenderPages()">Clear employee filter</button></div>':''}</div>
    <div class="settings-table-wrap"><table><thead><tr><th>Employee</th><th>Promotion</th><th>Issued</th><th>Status</th><th>Packet ID</th><th>Actions</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${esc(p.employee?.name||'Employee removed')}<div class="mini-note">${esc(p.employee?.eid||'')} · ${esc(p.employee?.shift||'')}</div></td><td>${esc(p.tier?.replace('-', ' → ')||'')}</td><td>${esc(promotionLocalDate(p.issuedAt))}</td><td>${esc(p.status||'')}</td><td><small>${esc(p.id||'')}</small></td><td><div class="td-actions">${p.status!=='Deleted'?`<button class="sm primary" onclick="openPromotionDigitalPacket('${esc(p.id)}')">Open Digital</button><button class="sm" onclick="printPromotionPacket('${esc(p.id)}')">Blank Preview / Print</button>`:''}${p.status==='Issued'&&promotionPacketCan('issue')?`<button class="sm" onclick="exportPromotionPortablePacket('${esc(p.id)}')">Export Supervisor HTML</button>`:''}${p.status==='Issued'&&promotionPacketCan('review')?`<button class="sm" onclick="openPromotionReviewModal('${esc(p.id)}')">Paper Review</button>`:''}${p.status==='Reviewed'&&promotionPacketCan('decide')?`<button class="sm gold" onclick="openPromotionDecisionModal('${esc(p.id)}')">Manager Decision</button>`:''}${canAdmin()?`<button class="sm ${p.status==='Deleted'?'':'danger'}" onclick="openPromotionDeleteModal('${esc(p.id)}','${p.status==='Deleted'?'restore':'delete'}')">${p.status==='Deleted'?'Restore':'Delete'}</button>`:''}</div></td></tr>`).join('')||'<tr><td colspan="6">No packets match the filter.</td></tr>'}</tbody></table></div></div>`;
}
function openPromotionForEmployee(id){window._promotionEmployeeFocus=String(id||'');navigate('promotion-packets')}
function renderEmployeeProfilePromotion(emp){
  const list=(promotionPackets.packets||[]).filter(p=>p.status!=='Deleted'&&String(p.employeeId)===String(emp.id)).sort((a,b)=>String(b.issuedAt).localeCompare(String(a.issuedAt)));
  return `<div class="card"><div class="card-title">Promotion Packets</div><div class="td-actions">${promotionPacketCan('issue')?`<button class="sm primary" onclick="openPromotionIssueModal('${esc(emp.id)}')">Issue Packet</button>`:''}<button class="sm" onclick="openPromotionForEmployee('${esc(emp.id)}')">Open Promotion Packets</button></div>${list.length?`<div class="profile-list">${list.map(p=>`<div class="profile-list-row"><strong>${esc(p.tier?.replace('-', ' → ')||'')} · ${esc(p.status||'')}</strong><br><span class="mini-note">${esc(promotionLocalDate(p.issuedAt))} · ID ${esc(p.id)}</span> ${hasCapability('promotion.view')?`<button class="sm" onclick="openPromotionDigitalPacket('${esc(p.id)}')">Open Digital</button>`:''} ${promotionPacketCan('review')||promotionPacketCan('decide')||promotionPacketCan('issue')?`<button class="sm" onclick="printPromotionPacket('${esc(p.id)}')">Blank Preview</button>`:''}</div>`).join('')}</div>`:'<p class="mini-note">No promotion packets issued.</p>'}</div>`;
}
function openPromotionDeleteModal(id,action){
  if(!canAdmin()||!promotionPacketCan(action))return;
  const p=promotionPacket(id);if(!p||((action==='restore')!==(p.status==='Deleted')))return;
  showModal(`<div class="modal-head"><div class="modal-title">${action==='delete'?'Delete':'Restore'} Promotion Packet</div><button onclick="closeModal()">Close</button></div><p>${esc(p.employee?.name||'')} · ${esc(p.tier?.replace('-', ' → ')||'')} · ${esc(p.id)}</p><div class="notice">${action==='delete'?'This removes the packet from the active register and employee profile. Its history remains in the audit record; you can restore it from the deleted view.':'Restore the prior packet status and its original questions, review, and decision.'}</div><label>Reason (at least 10 characters)</label><textarea id="promoDeleteReason" rows="3" placeholder="Document why this packet is being ${action==='delete'?'deleted':'restored'}"></textarea><div class="modal-actions"><button onclick="closeModal()">Cancel</button><button class="${action==='delete'?'danger':'primary'}" onclick="savePromotionDelete('${esc(id)}','${action}')">${action==='delete'?'Delete packet':'Restore packet'}</button></div>`);
}
function savePromotionDelete(id,action){
  const notes=val('promoDeleteReason')?.trim()||'';
  if(notes.length<10){toast('Enter a reason of at least 10 characters.');return}
  promotionCommand(action,{packetId:id,notes});
}
function openPromotionBank(tier='T1-T2'){
  if(!promotionPacketCan('scenario'))return;
  const t=(promotionPackets.templates||[]).find(x=>x.tier===tier);if(!t)return;
  const bank=t.scenarios||[];
  showModal(`<div class="modal-head"><div><div class="modal-title">Scenario Banks</div><div class="mini-note">Changes create a new template revision. Issued packets keep their original questions.</div></div><button onclick="closeModal()">Close</button></div>
    <div class="form-grid"><div><label>Promotion level</label><select onchange="openPromotionBank(this.value)">${(promotionPackets.templates||[]).map(x=>`<option value="${esc(x.tier)}" ${x.tier===tier?'selected':''}>${esc(x.tier.replace('-', ' → '))}</option>`).join('')}</select></div><div><label>Active scenarios / revision</label><p>${bank.filter(x=>x.active!==false).length} active · version ${esc(t.revision||1)}</p></div></div>
    <div class="notice">${tier==='T3-T4'?'Six distinct prompts: three leadership and three emergency, covering access, personnel, medical/fire, hazard/evacuation and compound incidents.':tier==='T1-T2'?'Six distinct prompts: two Gate, two Patrol, one BASE, and one professional readiness.':'Six distinct prompts: two Gate, two Patrol, one BASE, and one incident/report judgment.'} ${tier!=='T3-T4'&&bank.some(s=>!s.category)?'This manager-customized legacy bank was preserved; categorize all active scenarios to enable balanced draws.':''}</div>
    <div class="settings-table-wrap"><table><thead><tr><th>Scenario</th><th>Status</th><th>Actions</th></tr></thead><tbody>${bank.map(s=>`<tr><td><b>${esc(s.title||s.id)}</b><div class="mini-note">${esc(s.category||'Legacy')} · ${esc((s.prompt||'').slice(0,220))}${(s.prompt||'').length>220?'…':''}</div></td><td>${s.active===false?'Archived':'Active'}</td><td><button class="sm" onclick="openPromotionScenarioEdit('${esc(tier)}','${esc(s.id)}')">Edit</button> <button class="sm" onclick="togglePromotionScenario('${esc(tier)}','${esc(s.id)}',${s.active===false})">${s.active===false?'Restore':'Archive'}</button></td></tr>`).join('')}</tbody></table></div>
    <div class="modal-actions"><button onclick="closeModal()">Close</button><button class="primary" onclick="openPromotionScenarioEdit('${esc(tier)}')">+ Add Scenario</button></div>`);
}
function openPromotionScenarioEdit(tier,id=''){
  if(!promotionPacketCan('scenario'))return;
  const t=(promotionPackets.templates||[]).find(x=>x.tier===tier),s=t?.scenarios?.find(x=>x.id===id);
  const options=tier==='T3-T4'
    ?`<div class="form-grid"><div><label>Scenario group</label><select id="promoScenarioCategory" onchange="promotionScenarioFocusOptions(this.value)"><option value="leadership" ${s?.category!=='emergency'?'selected':''}>Leadership</option><option value="emergency" ${s?.category==='emergency'?'selected':''}>Emergency</option></select></div><div><label>Coverage focus</label><select id="promoScenarioFocus"></select></div></div>`
    :`<label>Coverage group</label><select id="promoScenarioCategory">${(tier==='T1-T2'?[['gate','Gate'],['patrol','Patrol'],['base','Base awareness'],['professional','Professional readiness']]:[['gate','Independent Gate'],['patrol','Independent Patrol'],['base','Independent Base'],['incident','Incident / reporting']]).map(([value,label])=>`<option value="${value}" ${(s?.category||'gate')===value?'selected':''}>${label}</option>`).join('')}</select><label>Evaluator follow-up fact · read after initial answer</label><textarea id="promoScenarioInject" rows="4">${esc(s?.inject||'')}</textarea>`;
  showModal(`<div class="modal-head"><div class="modal-title">${id?'Edit':'Add'} ${esc(tier.replace('-', ' → '))} Scenario</div><button onclick="openPromotionBank('${esc(tier)}')">Back</button></div><div class="notice">This prompt is read aloud. Keep answer keys out of the candidate packet. Edits apply only to future issues.</div><label>Scenario title</label><input id="promoScenarioTitle" maxlength="120" value="${esc(s?.title||'')}"><label>Candidate question and operational context</label><textarea id="promoScenarioPrompt" rows="8">${esc(s?.prompt||'')}</textarea>${options}<div class="modal-actions"><button onclick="openPromotionBank('${esc(tier)}')">Cancel</button><button class="primary" onclick="savePromotionScenario('${esc(tier)}','${esc(id)}')">Save Scenario</button></div>`);
  if(tier==='T3-T4')promotionScenarioFocusOptions(s?.category||'leadership',s?.focus||'');
}
async function savePromotionScenario(tier,id){
  const prompt=val('promoScenarioPrompt')?.trim(),title=val('promoScenarioTitle')?.trim()||'';
  if(!prompt||prompt.length<45){toast('Write a complete scenario question of at least 45 characters.');return}
  const category=val('promoScenarioCategory'),focus=tier==='T3-T4'?val('promoScenarioFocus'):'';
  await promotionCommand('scenario',{tier,scenarioId:id,title,prompt,category,focus,inject:tier==='T3-T4'?'':val('promoScenarioInject')?.trim()||'',active:true});
}
async function togglePromotionScenario(tier,id,active){
  const t=(promotionPackets.templates||[]).find(x=>x.tier===tier),s=t?.scenarios?.find(x=>x.id===id);
  if(!s||!confirm((active?'Restore':'Archive')+' this scenario for future packets?'))return;
  await promotionCommand('scenario',{tier,scenarioId:id,title:s.title||'',prompt:s.prompt,category:s.category||(tier==='T3-T4'?'leadership':'gate'),focus:s.focus||'priorities',inject:s.inject||'',active});
}
function promotionScenarioFocusOptions(category,selected=''){
  const el=document.getElementById('promoScenarioFocus');if(!el)return;
  const groups={leadership:[['access','Access control'],['personnel','Personnel / coverage'],['safety','Safety'],['priorities','Prioritization'],['hazard','Hazard'],['fire','Fire'],['evacuation','Evacuation'],['injury','Injury']],emergency:[['medicalFire','Medical / fire'],['hazardEvac','Hazard / evacuation'],['compound','Compound incident']]};
  el.innerHTML=(groups[category]||groups.leadership).map(([id,label])=>`<option value="${id}" ${selected===id?'selected':''}>${label}</option>`).join('');
}
function openPromotionIssueModal(employeeId=''){
  if(!promotionPacketCan('issue'))return;
  const employees=(roster.employees||[]).filter(e=>!isArchivedEmployee(e)).sort((a,b)=>fullName(a).localeCompare(fullName(b)));
  showModal(`<div class="modal-head"><div><div class="modal-title">Issue Promotion Packet</div><div class="mini-note">The selected six questions are frozen on issue and available in print, Suite, and offline HTML.</div></div><button onclick="closeModal()">Close</button></div><div class="form-grid"><div><label>Candidate</label><select id="promoEmployee"><option value="">Choose employee</option>${employees.map(e=>`<option value="${esc(e.id)}" ${String(e.id)===String(employeeId)?'selected':''}>${esc(fullName(e))} · ${esc(e.eid||'')}</option>`).join('')}</select></div><div><label>Promotion Level</label><select id="promoTier">${(promotionPackets.templates||[]).filter(t=>t.active!==false).map(t=>`<option value="${esc(t.tier)}">${esc(t.tier.replace('-', ' → '))} · ${(t.scenarios||[]).filter(s=>s.active!==false).length} active scenarios</option>`).join('')}</select></div></div><div class="notice">Check the candidate's current qualifications before issuance. The packet captures a snapshot of Training assignments; missing signoffs do not become qualifications.</div><div class="modal-actions"><button onclick="closeModal()">Cancel</button><button onclick="issuePromotionPacket('print')">Issue and Preview Print</button><button onclick="issuePromotionPacket('digital')">Issue and Open Digital</button><button class="primary" onclick="issuePromotionPacket('portable')">Issue and Export Supervisor HTML</button></div>`);
}
async function issuePromotionPacket(destination='print'){
  const employeeId=val('promoEmployee'),tier=val('promoTier');
  if(!employeeId||!tier){toast('Choose an employee and promotion level.');return}
  const res=await promotionCommand('issue',{employeeId,tier});
  if(res?.packetId){if(destination==='digital')openPromotionDigitalPacket(res.packetId);else if(destination==='portable')exportPromotionPortablePacket(res.packetId);else printPromotionPacket(res.packetId)}
}
function openPromotionReviewModal(id){
  if(!promotionPacketCan('review'))return;
  const p=promotionPacket(id);if(!p||p.status!=='Issued')return;
  showModal(`<div class="modal-head"><div class="modal-title">Evaluator / Supervisor Recommendation</div><button onclick="closeModal()">Close</button></div><p>${esc(p.employee?.name||'')} · ${esc(p.tier?.replace('-', ' → ')||'')} · ${esc(p.id)}</p><div class="notice">Use this form for a paper packet. Evaluate the comprehensive checklist and grade all six verbal responses on the printed packet. For an on-screen assessment, open the digital packet instead. Document key answers, live or simulated evaluation evidence, gaps, and rechecks. A recommendation may include a documented Needs Development item. File the signed packet or controlled scan.</div><div class="form-grid"><div><label>Recommendation</label><select id="promoRecommendation"><option value="Recommend">Recommend</option><option value="Return for development">Return for development</option></select></div><div><label>Completed packet / scan reference</label><input id="promoReference" placeholder="Controlled file or paper record location"></div><div class="full"><label>Assessment and specific gaps</label><textarea id="promoNotes" rows="5" placeholder="Summarize checklist evidence, verbal scenario grades, and follow-up"></textarea></div></div><div class="modal-actions"><button onclick="closeModal()">Cancel</button><button class="primary" onclick="savePromotionReview('${esc(id)}')">Save Recommendation</button></div>`);
}
function savePromotionReview(id){
  const reference=val('promoReference')?.trim(),notes=val('promoNotes')?.trim();
  if(!reference||!notes){toast('Completed packet reference and assessment are required.');return}
  promotionCommand('review',{packetId:id,recommendation:val('promoRecommendation'),reference,notes});
}
function openPromotionDecisionModal(id){
  if(!promotionPacketCan('decide'))return;
  const p=promotionPacket(id);if(!p||p.status!=='Reviewed')return;
  const interview=p.tier==='T3-T4'?`<div class="full"><h3>Required T4 Security Manager interview</h3><div class="mini-note">Discuss leadership judgment, incident response, training integrity, and Acting Supervisor limits. Approval requires a dated interview rated Meets standard.</div></div><div><label>Interview date</label><input id="promoInterviewDate" type="date"></div><div><label>Interview outcome</label><select id="promoInterviewOutcome"><option value="">Select outcome</option><option>Meets standard</option><option>Needs development</option></select></div><div class="full"><label>Interview assessment</label><textarea id="promoInterviewNotes" rows="4" placeholder="Record the candidate's responses and your assessment"></textarea></div>`:'';
  const names=promotionGateNamesFor(p.tier);
  const digital=p.review?.mode==='digital';
  const gateSelects=`<div class="full"><h3>${names.length}-gate final review</h3><p class="mini-note">Record each gate from the signed workbook. All gates must pass for promotion approval; document every gap and recheck.</p></div>${names.map((name,i)=>`<div><label>Gate ${i+1} · ${esc(name)}</label><select id="promoGate${i+1}"><option value="">Not determined</option><option ${digital&&p.digitalAssessment?.gates?.[String(i+1)]?.status==='PASS'?'selected':''}>PASS</option><option ${digital&&p.digitalAssessment?.gates?.[String(i+1)]?.status==='REMEDIATE'?'selected':''}>REMEDIATE</option><option ${digital&&p.digitalAssessment?.gates?.[String(i+1)]?.status==='HOLD'?'selected':''}>HOLD</option><option ${digital&&p.digitalAssessment?.gates?.[String(i+1)]?.status==='NOT ELIGIBLE'?'selected':''}>NOT ELIGIBLE</option></select></div>`).join('')}`;
  showModal(`<div class="modal-head"><div class="modal-title">Security Manager Approval</div><button onclick="closeModal()">Close</button></div><p>${esc(p.employee?.name||'')} · ${esc(p.tier?.replace('-', ' → ')||'')} · ${esc(p.id)}</p><div class="notice">Supervisor: ${esc(p.review?.recommendation||'')} · ${esc(p.review?.reviewerName||'')}<br>${esc(p.review?.notes||'')}${digital?`<br>Digital assessment submitted. <button onclick="closeModal();openPromotionDigitalPacket('${esc(id)}','overview')">Review Full Digital Packet</button>`:''}</div><div class="form-grid"><div><label>Decision</label><select id="promoDecision"><option value="Approve promotion">Approve promotion</option><option value="Defer">Defer</option><option value="Decline">Decline</option></select></div><div><label>Signed packet / scan reference</label><input id="promoDecisionReference" value="${esc(p.review?.paperReference||'')}"></div><div class="full"><label><input type="checkbox" id="promoRecordsVerified"> Signed qualifications and eligibility records verified</label></div><div class="full"><label><input type="checkbox" id="promoChecklistReviewed"> Completed checklist and supporting evidence reviewed</label></div><div class="full"><label><input type="checkbox" id="promoScenariosReviewed"> All six verbal scenario grades and evaluator notes reviewed</label></div>${interview}${gateSelects}<div class="full"><label>Decision basis and HR follow-up</label><textarea id="promoDecisionNotes" rows="5" placeholder="Record approval or deferral rationale and any HR follow-up"></textarea></div></div><div class="modal-actions"><button onclick="closeModal()">Cancel</button><button class="primary" onclick="savePromotionDecision('${esc(id)}')">Record Decision</button></div>`);
}
function savePromotionDecision(id){
  const p=promotionPacket(id),decision=val('promoDecision');
  const reference=val('promoDecisionReference')?.trim(),notes=val('promoDecisionNotes')?.trim();
  const recordsVerified=document.getElementById('promoRecordsVerified')?.checked===true;
  const checklistReviewed=document.getElementById('promoChecklistReviewed')?.checked===true;
  const scenariosReviewed=document.getElementById('promoScenariosReviewed')?.checked===true;
  const interviewDate=val('promoInterviewDate')||'',interviewOutcome=val('promoInterviewOutcome')||'',interviewNotes=val('promoInterviewNotes')?.trim()||'';
  if(!reference||!notes){toast('Signed packet reference and decision reason are required.');return}
  if(decision==='Approve promotion'&&(!recordsVerified||!checklistReviewed||!scenariosReviewed)){toast('Verify signed records, checklist, and all six verbal grades before approval.');return}
  if(decision==='Approve promotion'&&p?.tier==='T3-T4'&&(!interviewDate||interviewOutcome!=='Meets standard'||interviewNotes.length<20)){toast('T4 approval requires a dated Manager interview, Meets standard rating, and assessment.');return}
  const gateStatuses=Object.fromEntries(promotionGateNamesFor(p?.tier).map((_,i)=>['Gate '+(i+1),val('promoGate'+(i+1))||'']));
  if(decision==='Approve promotion'&&Object.values(gateStatuses).some(x=>x!=='PASS')){toast('All evidence gates must be recorded PASS before approval.');return}
  promotionCommand('decide',{packetId:id,decision,reference,notes,recordsVerified,checklistReviewed,scenariosReviewed,interviewDate,interviewOutcome,interviewNotes,gateStatuses});
}
function printPromotionPacket(id){
  if(!promotionPacketCan('review')&&!promotionPacketCan('decide')&&!promotionPacketCan('issue')){toast('Evaluator access is required to preview a promotion packet.');return}
  const p=promotionPacket(id);if(!p||p.status==='Deleted')return;
  if(!Array.isArray(p.scenarios)||p.scenarios.length!==6){toast('This packet does not contain exactly six scenarios.');return}
  const style=`<style>@page{size:letter;margin:.58in}*{box-sizing:border-box}body{font-family:"Century Gothic",Arial,sans-serif!important;color:#171717!important;background:white!important;font-size:9.5pt!important;line-height:1.35!important}.pp-header{border-top:8px solid #c8102e;padding-top:10px}.pp-brand{font-size:9pt;font-weight:700;letter-spacing:1.5px}.pp-header h1{font-size:21pt;color:#c8102e;margin:4px 0}.pp-meta{color:#555;font-size:8pt}.pp-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin:15px 0}.pp-field{border-bottom:1px solid #888;min-height:37px;padding:4px 2px}.pp-field b{font-size:7.5pt;color:#555;text-transform:uppercase;letter-spacing:.4px}.pp-note{background:#f8f5f3;border-left:4px solid #c8102e;padding:10px;margin:12px 0}.pp-section{break-before:page;page-break-before:always}.pp-heading{color:#c8102e;border-bottom:2px solid #c8102e;padding-bottom:5px;margin:8px 0 10px;font-size:15pt}.pp-subheading{font-size:11pt;color:#111;border-bottom:1px solid #aaa;margin:18px 0 6px;padding-bottom:3px}.pp-check{padding:8px 0;border-bottom:1px solid #ddd;break-inside:avoid;page-break-inside:avoid}.pp-check-title{font-weight:700}.pp-eval{font-size:8pt;margin-top:5px;color:#333}.pp-scenario{padding:12px;border:1px solid #bbb;margin:12px 0;break-inside:avoid;page-break-inside:avoid}.pp-scenario h3{margin:0 0 5px;font-size:11pt;color:#c8102e}.pp-line{border-bottom:1px solid #999;min-height:26px;margin:5px 0}.pp-sign{min-height:55px;border-bottom:1px solid #888;margin:10px 0}.pp-small{font-size:8pt;color:#555}.pp-footer{font-size:8pt;border-top:1px solid #999;margin-top:18px;padding-top:5px}table{width:100%;border-collapse:collapse;font-size:8pt}th,td{border:1px solid #aaa;padding:5px;text-align:left;vertical-align:top}th{background:#f1efec}tr{break-inside:avoid}@media print{.printbar,.report-print-toolbar{display:none!important}}</style>`;
  const header=`<div class="pp-header"><div class="pp-brand">PIGGLY WIGGLY ALABAMA DISTRIBUTING COMPANY · SECURITY</div><h1>Promotion Assessment & Approval</h1><div class="pp-meta">${esc(p.tier?.replace('-', ' → ')||'')} · Packet ${esc(p.id)} · Template revision ${esc(p.templateRevision||1)}</div></div><div class="pp-grid"><div class="pp-field"><b>Candidate</b><br>${esc(p.employee?.name||'')}</div><div class="pp-field"><b>Employee ID</b><br>${esc(p.employee?.eid||'')}</div><div class="pp-field"><b>Current rank / shift</b><br>${esc(p.employee?.rank||'')} · ${esc(p.employee?.shift||'')}</div><div class="pp-field"><b>Issued / assessment date</b><br>${esc(promotionLocalDate(p.issuedAt))} / __________________</div><div class="pp-field"><b>Evaluator / supervisor</b><br>______________________________</div><div class="pp-field"><b>Security Manager</b><br>______________________________</div></div><div class="pp-note"><b>Evaluator instructions:</b> Verify signed qualifications and required review-window records. Ask all six scenarios aloud; the candidate answers verbally. Grade each response and record key points, gaps, and follow-up. Coaching and incident evaluations may be observed live or conducted as controlled simulations; document the method, exercise or event, evaluator, date, and outcome against the same standard. A simulation does not establish an actual signed post qualification or historical conduct record. The Security Manager reviews this completed packet for final approval.</div>`;
  const missingTraining=(p.trainingEvidence||[]).filter(x=>!x.signoffId);
  const evidence=missingTraining.length?`<h2 class="pp-subheading">Missing training at issue</h2><table><thead><tr><th>Assigned requirement</th><th>Snapshot gap</th><th>Resolution / signed record and date</th></tr></thead><tbody>${missingTraining.map(x=>`<tr><td>${esc(x.requirement||'')}</td><td>No current signoff in snapshot</td><td style="height:42px"></td></tr>`).join('')}</tbody></table><p class="pp-small">This issue-time list shows assigned training without a current signoff. Verify the signed source records and resolve each gap before approval.</p>`:'';
  const checklist=p.tier==='T3-T4'?promotionT4Gates(p):promotionLowerGates(p);
  const scenarios=p.tier==='T3-T4'?promotionT4Scenarios(p):promotionLowerScenarios(p);
  const supervisor=p.tier==='T3-T4'?promotionT4Supervisor(p):promotionLowerSupervisor(p);
  const interview=p.tier==='T3-T4'?promotionT4Interview(p):'';
  const decision=p.tier==='T3-T4'?promotionT4Decision(p):promotionLowerDecision(p);
  openReportWindow(style+header+evidence+checklist+scenarios+supervisor+interview+decision,false,'portrait');
}
const promotionLowerGateNames={"T1-T2":["Eligibility and signed trainee record","Gate fundamentals under supervision","Patrol fundamentals under supervision","BASE awareness and emergency response","Professional readiness and pass-down"],"T2-T3":["Eligibility, qualifications, and 60-day review","Independent Gate mastery","Independent Patrol mastery","Independent BASE mastery","Incident reporting and response judgment","Professional conduct and complete handoff"]};
function promotionGateNamesFor(tier){return tier==='T3-T4'?promotionT4GateNames:(promotionLowerGateNames[tier]||[])}

function promotionLowerCheckRows(p,sections){
 const rows=(p.checklist||[]).filter(x=>sections.includes(x.section));
 if(!rows.length)return '';
 return `<table><thead><tr><th style="width:54%">Required standard</th><th>Status</th><th>Source / date / evaluator</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.id||'')}</b> · ${esc(x.text||'')}</td><td>□ Verified<br>□ Gap<br>□ Not observed</td><td style="height:54px"></td></tr>`).join('')}</tbody></table>`;
}

function promotionLowerGate(p,index,sections,extra){
 const title=promotionGateNamesFor(p.tier)[index-1];
 return `<div class="pp-section"><h2 class="pp-heading">Gate ${index} · ${esc(title)}</h2>${promotionLowerCheckRows(p,sections)}${extra}<div class="pp-note"><b>Gate ${index} final status:</b> □ PASS □ REMEDIATE □ HOLD □ NOT ELIGIBLE &nbsp; Critical failure: □ Yes □ No<br>Supporting evidence and observed date: __________________________________________________________________<br>Evaluator signature: _______________________ Date: __________ &nbsp; Recheck date if needed: __________</div></div>`;
}
function promotionEvaluationMethod(){
 return `<p><b>Evaluation method:</b> □ Live event / coaching &nbsp; □ Simulated exercise<br>Event or exercise ID: __________________ &nbsp; Evaluator: __________________ &nbsp; Date: __________</p>`;
}
// Gate exercises are printed with the assessment, so an evaluator can administer a
// controlled simulation without inventing facts or relying on the six oral questions.
const promotionGateExercises={
 'T1-BASE':{title:'Unconfirmed alarm near an occupied area',prompt:'You are a Trainee at the Gate when BASE radios that an alarm has appeared near an occupied warehouse area. A coworker asks you to go investigate and silence it. You can see a vehicle arriving at your lane, and your qualified Officer is helping another driver. Explain what you say over the radio, how you keep the lane safe, what facts you pass to the qualified Officer, and what you will not do on your own.',inject:'BASE reports that a worker may be in the affected area. Explain how your urgency and notifications change while following the current EAP and your Trainee authority.',task:'Evaluate clear facts, safe withdrawal, 911 recognition, escalation, and role limits.'},
 'T1-COACH':{title:'Receiving corrective Gate coaching',prompt:'During a supervised Gate exercise, you started to wave a familiar delivery driver forward before the badge result appeared. The qualified Officer stopped the vehicle and explains that a familiar driver still must badge and that a failed or missing badge is handled under the Gate Reference. Role-play receiving this correction, explaining the safe process back to the Officer, and then repeating the encounter correctly.',inject:'The role-play driver says Dispatch is expecting them and the lane is backing up. Show how you hold safely and ask the qualified Officer for direction without making an independent access decision.',task:'Evaluate whether the candidate accepts coaching, demonstrates the correction, and documents the recheck.'},
 'T2-REPORT1':{title:'Unsecured door and uncertain timeline',prompt:'You discover a warehouse side door unsecured during patrol at approximately 10:14. No person is seen entering or leaving. A warehouse employee says it may have been opened for maintenance but cannot give a name or time. BASE confirms receiving your radio call at 10:17. Using only these facts, write an incident report with your observations, the attributed statement, notifications, and unanswered questions.',inject:'The evaluator adds that a camera bookmark exists, but no footage has been reviewed. Update the evidence reference without claiming the footage proves who opened the door.',task:'Assess chronology, fact versus statement, source attribution, escalation and a complete report.'},
 'T2-REPORT2':{title:'Loading-area injury with conflicting accounts',prompt:'At 13:40 you arrive near an active dock after a report that a worker fell. You observe the worker seated and alert, with another employee standing nearby. One witness says the worker slipped; another says a pallet jack was close to the worker. You did not see the fall. Draft the security report and explain which notifications you make under the current injury and emergency procedures.',inject:'A coworker asks you to write that the pallet jack caused the injury. Revise or defend your wording using firsthand facts and clearly attributed statements.',task:'Assess safety priority, neutral wording, medical uncertainty, witness attribution and notification trail.'},
 'T2-REPORT3':{title:'Denied badge and pressured access request',prompt:'A driver arrives with a delivery and presents a badge that does not open the Gate. The driver says the appointment is urgent; the warehouse contact is not immediately available. You hold the vehicle safely, consult the current Gate Reference, and contact qualified support. Draft the incident or exception record showing what you observed, who supplied each statement, the decision and the final disposition.',inject:'Dispatch later provides a different trailer number. Record the new information and explain who verifies the discrepancy before any access decision.',task:'Assess complete access chronology, sources, authority, escalation, and factual final disposition.'},
 'T2-INCIDENT':{title:'Possible ammonia odor during patrol',prompt:'While on patrol near a refrigerated area, you notice a strong unfamiliar odor and see two workers leaving the area quickly. One says they think it could be ammonia; no release is confirmed. Another officer asks you to go closer to identify the source. Describe your immediate safety actions, information sent to BASE and the Supervisor, and how you use the current controlled EAP without entering an unsafe area.',inject:'BASE reports that a worker may still be inside and a second caller reports eye irritation. Reassess emergency notification, isolation, responder access, and the facts you would document.',task:'Assess life safety, safe withdrawal, qualified escalation, current EAP use and factual chronology.'},
 'T2-COACH':{title:'Repeated missed hazard in a junior officer handoff',prompt:'A junior officer handing off patrol reports says every assigned area is clear, but you notice an obstructed emergency exit in their area. The officer says it is probably temporary and was not in the log. Within T2 authority, role-play a factual correction, immediate safety escalation and a demonstration of the required patrol report and handoff. Do not treat this as authority to issue discipline or sign off training you did not verify.',inject:'At the recheck, the officer has reported the obstruction but leaves the incident time blank. Show the second coaching step and when the Lead or Supervisor must take over.',task:'Assess safe intervention, respectful coaching, escalation, documentation and independently verified recheck.'},
 'T4-BASE1':{title:'Two simultaneous BASE calls',prompt:'At BASE you receive a Gate radio request about a badge denial while a Patrol officer reports a possible medical emergency in a warehouse aisle. Cameras show activity near the aisle but do not establish a diagnosis. Demonstrate how you prioritize the calls, keep radio traffic clear, dispatch qualified coverage, make or direct emergency notifications under the current EAP, and keep the BASE log chronological.',inject:'While the medical response is forming, the Gate driver becomes argumentative and a second camera alarm appears. Reprioritize and explain which tasks you delegate or escalate to the Supervisor.',task:'Assess priority, dispatch, 911 judgment, authority limits, access control and accurate log entries.'},
 'T4-BASE2':{title:'Alarm, camera review and system degradation',prompt:'On a different date or shift, BASE receives a critical alarm near a restricted area. The camera view is intermittent, a Patrol officer is nearby, and the Gate asks for coverage while its officer assists a visitor. Demonstrate radio coordination, safe response, camera navigation or available exercise footage review, qualified coverage, and the incident timeline. Do not assume the alarm cause or export video outside your authority.',inject:'The camera feed fails completely and Patrol reports an unclear odor. Reassess life safety, current EAP activation, critical system failure reporting, and evidence preservation.',task:'Assess multitasking, system failure escalation, forensic references, coverage and Manager review.'},
 'T4-COACH':{title:'Trainee bypasses a denied badge step',prompt:'You are the acting FTO for a simulated Trainee at the Gate. The Trainee recognizes a regular vendor and starts to direct them through after the badge fails, saying the vendor has entered before. Role-play stopping the unsafe action, explaining the current badge and verification standard, demonstrating the correct interaction, and observing the Trainee repeat it. A separate evaluator plays the Trainee and verifies your coaching.',inject:'The Trainee performs the next attempt correctly but skips documentation and asks you to sign the qualification immediately. Show the correction, evidence you would require, and whether you would withhold signoff.',task:'Assess instruction, fair observation, corrective feedback, recheck, record integrity and independent verification.'},
 'T4-LEAD1':{title:'Access pressure at the Gate',prompt:'A driver with a failed badge says Receiving knows them and a warehouse employee urges the Gate officer to admit them because trucks are backing up. The officer calls you as Lead while BASE is monitoring a separate alarm. Take command of the immediate access decision within Lead authority, direct safe lane control, verify the appropriate source and notify the Supervisor where required.',inject:'Dispatch gives a trailer number that differs from the driver paperwork. Explain the revised decision, documentation and how you prevent pressure from producing an unauthorized exception.',task:'Assess access judgment, role limits, clear directions, fairness and escalation.'},
 'T4-LEAD2':{title:'Coverage gap and contested assignment',prompt:'At shift change, a qualified BASE officer is late and an unqualified officer volunteers to cover BASE. At the same time a Patrol officer says the Gate officer owes them a favor and should swap posts. As Lead, organize temporary qualified coverage, communicate the gap to the Supervisor, give fair instructions and preserve the handoff record. Do not grant an unqualified person independent post authority.',inject:'The late officer texts that they will be another thirty minutes, and a safety call comes from Patrol. Reprioritize coverage and explain who makes the staffing decision.',task:'Assess personnel judgment, qualified coverage, communication and professional boundaries.'},
 'T4-LEAD3':{title:'Safety report while operational demands continue',prompt:'A Patrol officer radios that a forklift route is blocked and a worker may have been hurt nearby. Gate traffic is heavy and another officer asks to leave post to investigate. As Lead, state the immediate safety priorities, assign only qualified resources, coordinate with BASE and the Supervisor, and describe the information needed before any operational decision.',inject:'A second caller reports an unfamiliar odor in the same area. Explain how you reassess the scene, direct withdrawal and emergency coordination under the current EAP without assuming a cause.',task:'Assess life safety, delegation, emergency escalation, post coverage and factual updates.'},
 'T4-REPORT1':{title:'Candidate report: unattended restricted door',prompt:'Prepare a candidate-authored security report from these exercise facts: at 06:18 Patrol found a restricted door ajar; at 06:21 BASE logged the call; a maintenance worker later said they might have used the door but offered no time. You did not observe anyone enter. Include firsthand facts, attributed statements, notifications, unresolved questions, and the record or footage references actually available.',inject:'At 07:05 a Supervisor reports that the door was secured. Add the update without changing the original observations or treating the worker statement as a confirmed cause.',task:'Assess source, chronology, completeness, routing and material follow-through.'},
 'T4-REPORT2':{title:'Candidate report: injury near a dock',prompt:'Prepare a second report from an exercise where you arrive at 11:32 after a worker is reported injured beside an active dock. The worker is alert; one witness says there was a slip and another mentions a nearby pallet jack. You did not witness the injury. Document the scene, exact sources, safety notifications and response chronology under the current procedure.',inject:'A manager asks you to state that a specific employee caused the injury. Explain why you would record a supported statement or observation only, and add any new verified fact as a dated update.',task:'Assess neutral fact finding, unsupported causation, notifications and escalation.'},
 'T4-REPORT3':{title:'Candidate report: badge mismatch and later update',prompt:'Prepare a third report from a Gate exercise: at 15:06 a badge did not authorize entry; the driver claimed an appointment; the displayed trailer number differs from the Gate Reference. The Gate officer held the vehicle safely and contacted Dispatch. State what you personally verified versus what others reported and document the decision path and disposition.',inject:'At 15:19 Dispatch supplies revised appointment information but cannot confirm the trailer. Update the report without inventing an entry or release time.',task:'Assess improvement, authority, access chronology and accurate resolution.'},
 'T4-SHADOW1':{title:'Shadow review: omitted door notification',prompt:'Review a simulated officer draft that says, “Door was open around six. Maintenance probably left it. I secured it and nothing happened.” The exercise log shows a BASE notification at 06:21, but the draft gives no discovery time, source for the maintenance claim, or record of who secured the door. Decide whether to accept, return for correction, or escalate and state the material omissions.',inject:'The author says their memory is good enough and proposes adding a made-up time. Explain how you preserve the original facts while seeking accurate sources and Supervisor review.',task:'Assess unsupported conclusion, chronology, notification and correction without rewriting another account.'},
 'T4-SHADOW2':{title:'Shadow review: unsupported injury conclusion',prompt:'Review a simulated officer draft that states, “A pallet jack caused a worker to fall; no further action needed.” The officer arrived after the event; two witnesses disagree and the draft omits the worker’s observed condition, emergency notifications, and their times. Decide accept, return, or escalate, and identify the missing sources and operational concerns.',inject:'A caller later reports worsening symptoms. State how you update priority and notifications under the current EAP and preserve the original witness accounts.',task:'Assess medical uncertainty, source attribution, life safety and material report deficiencies.'},
 'T4-SHADOW3':{title:'Shadow review: access disposition omitted',prompt:'Review a simulated Gate incident draft: “Driver had a bad badge. Dispatch fixed it. Truck left.” The record contains a trailer discrepancy, but the draft omits who verified it, who authorized the final decision, whether entry occurred, and the actual departure time. Decide accept, return, or escalate and explain the operational risk of those gaps.',inject:'The author asks you to fill the missing times from memory and sign the report for them. Explain the proper correction path and when to involve the Supervisor.',task:'Assess access authority, complete disposition, factual integrity and report review judgment.'},
 'T4-FLAWED':{title:'Formal flawed report: uncertain odor and missed response',prompt:'Review this simulated report excerpt: “At about 9 an ammonia leak happened by the cooler. Everyone was fine. I checked the cameras and saved the video. Maintenance handled it.” Supporting exercise facts show only an unfamiliar odor reported at 09:12, a worker who described eye irritation at 09:16, a BASE radio call at 09:18, and no documented responder notification or verified release source. Decide Accept, Return, or Escalate. Identify every unsupported statement and material safety, notification, timeline, evidence and authority issue.',inject:'The author tells you that a manager wants the word “ammonia” left in the report because the alarm panel displayed it. Explain how to attribute the panel indication, verify the current EAP response and preserve the original account.',task:'Assess material incident failures, correction path, current emergency procedure and video-export authority.'}
};
function promotionGateExercise(id){
 const x=promotionGateExercises[id];if(!x)throw Error('Unknown promotion exercise: '+id);
 return `<div class="pp-note"><b>Provided simulation ${esc(id)} · ${esc(x.title)}</b><br><b>Read to candidate:</b> ${esc(x.prompt)}<br><b>Then introduce:</b> ${esc(x.inject)}<br><b>Evaluate:</b> ${esc(x.task)}</div><div class="pp-sign">Candidate actions, follow-up, outcome and recheck:</div>`;
}

function promotionLowerGates(p){
 const t1=p.tier==='T1-T2';
 const start=`<div class="pp-section"><h2 class="pp-heading">Review initiation · ${esc(p.tier.replace('-',' → '))}</h2><p>This is a confidential promotion evidence record. Give every gate a source, date, and evaluator. Coaching and incident evaluations may use a documented live event or controlled simulation graded to the same standard. Verify signed post qualifications, actual work records, and required review-window history separately. Do not offset a critical safety, access, integrity, or authority failure with an unrelated strength.</p>${promotionT4FieldGrid(['Current classification and effective date','Review start / review end','Lead evaluator and Security Supervisor','Security Manager / packet custodian'])}${promotionT4Form(['Current rank and active employment verified','Review requirements and controlled handbook versions identified','Candidate informed of the evaluation process','Current signed qualifications and Training assignments checked'],'YES / NO / HOLD')}</div>`;
 if(t1){
  return start+
   promotionLowerGate(p,1,['Required file and eligibility'],`<p>Verify the 90-day probation, approved absence records, signed OJT-001 and all required PMC-T1 components. A missing mandatory qualification remains a hold; a scenario cannot supply a signature.</p>${promotionT4FieldGrid(['Probation completion date','Attendance review dates','OJT-001 signed record','PMC-T1 file reference'])}`)+
   promotionLowerGate(p,2,['Gate fundamentals under supervision'],`<h3 class="pp-subheading">Observed supervised Gate practical</h3>${promotionT4FieldGrid(['Date / time / shift','Qualified observer','Gate scenario or actual traffic period','Current Gate Reference version'])}${promotionT4Form(['Badge and denied/no-badge process followed under direction','Driver, visitor and vendor verification routed to qualified personnel','Trainee verbal hold and safe lane control','No independent grant or denial of access','Factual communications and Gate record'])}<div class="pp-sign">Observed actions, qualified Officer decision, and recheck if needed:</div>`)+
   promotionLowerGate(p,3,['Patrol fundamentals under supervision'],`<h3 class="pp-subheading">Observed supervised Patrol practical</h3>${promotionT4FieldGrid(['Date / time / shift','Qualified patrol observer','Actual round / route','Patrol log reference'])}${promotionT4Form(['Safe movement around forklifts, trucks and active docks','Observes and reports unsecured or restricted areas factually','Prompt radio report to BASE and Supervisor','Genuine completed or delayed patrol documentation'])}<div class="pp-sign">Observed actions and specific coached behavior:</div>`)+
   promotionLowerGate(p,4,['Base awareness and emergency response'],`<h3 class="pp-subheading">BASE familiarization and emergency verbal practical</h3>${promotionEvaluationMethod()}${promotionGateExercise('T1-BASE')}${promotionT4FieldGrid(['Current EAP version reviewed','Incident or practice example'])}${promotionT4Form(['Relays location, hazards and facts without guessing','Recognizes when a clear emergency warrants 911','Explains BASE officer versus Trainee authority','Withdraws safely and follows current EAP direction','Avoids independent system control and unauthorized re-entry'])}<div class="pp-sign">Candidate's response, evaluator follow-up and required recheck:</div>`)+
   promotionLowerGate(p,5,['Professional readiness'],`<p>Supervisor reviews real shift conduct, honest records, radio discipline and complete pass-down before T2 independent development. Coaching skill may also be evaluated in a controlled role-play.</p>${promotionT4Form(['Actual post-relief and pass-down observed','Logs sampled for accuracy and integrity','Respectful communication under disagreement'])}<h3 class="pp-subheading">Coaching and response practical</h3>${promotionEvaluationMethod()}${promotionGateExercise('T1-COACH')}${promotionT4Form(['Clear corrective coaching delivered','Candidate receives feedback and demonstrates improvement'])}${promotionT4FieldGrid(['Supervisor conduct review date','Record samples / shift references'])}`);
 }
 return start+
  promotionLowerGate(p,1,['Required file and review window'],`<h3 class="pp-subheading">60-day record and eligibility audit</h3>${promotionT4FieldGrid(['Review-window start / end','PMC-Officer v2.0 signed file','Manager documentation audit reference','Disciplinary eligibility reviewer'])}${promotionT4Form(['PMC section average at least 2.5 and no required item scored 1','Documentation accuracy at least 98% during preceding 60 days','Sixty-day documented solo patrol pattern and valid delays','No active Step 2 Written Warning or higher','Signed independent Gate, Patrol and BASE qualifications'],'YES / NO / HOLD')}`)+
  promotionLowerGate(p,2,['Independent Gate mastery'],`<h3 class="pp-subheading">Independent Gate practical and record sample</h3>${promotionT4FieldGrid(['Evaluation date / shift','Authorized observer','Gate Reference version','Inbound and designated outbound record sample'])}${promotionT4Form(['Denied/no-badge access verified and controlled','Visitor BASE and vendor appointment/routing verification','Designated carrier pass checks only','PWADC/Pig badge, truck, trailer and seal compared','Pass discrepancy sent back to Dispatch without holding truck'])}<div class="pp-sign">Decision, authority basis and actual outcome:</div>`)+
  promotionLowerGate(p,3,['Independent Patrol mastery'],`<h3 class="pp-subheading">Independent patrol practical and 60-day record</h3>${promotionT4FieldGrid(['Observed round / shift','Patrol observer','Patrol logs / sample dates','Missed or delayed rounds reviewed'])}${promotionT4Form(['Safe situational awareness around active traffic and docks','Access, safety, maintenance and seal concerns reported','BASE, Supervisor, Dispatch or warehouse coordination','No separate Dock/Crosswalk standing post or release inspection','Accurate rounds and required post coverage'])}<div class="pp-sign">Observed judgment and specific supporting events:</div>`)+
  promotionLowerGate(p,4,['Independent Base mastery'],`<h3 class="pp-subheading">Independent BASE practical</h3>${promotionT4FieldGrid(['Evaluation date / shift','Authorized BASE evaluator','Monitoring / incident period','BASE log / footage reference'])}${promotionT4Form(['Active camera monitoring and incident intake','Radio dispatch and qualified coverage','Immediate 911 decision when clearly required','Event bookmark extends at least 30 seconds before and after','No video export below Lead authority','Critical system failure reported through approved chain'])}<div class="pp-sign">Observed priorities, decisions, notifications and chronology:</div>`)+
  promotionLowerGate(p,5,['Incident, reporting, and judgment'],`<h3 class="pp-subheading">Candidate-authored incident report audit</h3><p>Use actual incident reports or controlled simulated cases; record the method and report IDs.</p>${promotionEvaluationMethod()}${['T2-REPORT1','T2-REPORT2','T2-REPORT3'].map(promotionGateExercise).join('')}${promotionT4Form(['Report sample 1 · source, chronology and complete facts','Report sample 2 · observation, statements and opinion separated','Report sample 3 · evidence references and proper routing'])}<h3 class="pp-subheading">Incident / current EAP judgment practical</h3>${promotionEvaluationMethod()}${promotionGateExercise('T2-INCIDENT')}${promotionT4FieldGrid(['EAP version verified','911 / Supervisor notification sequence'])}${promotionT4Form(['Life safety and safe withdrawal','Fire, ammonia, injury, spill or weather recognition','Threat, posturing or repeated noncompliance escalated','Factual documentation without altering another account'])}`)+
  promotionLowerGate(p,6,[],`<p>Use the shift handoff standard and independent Officer conduct, including the last checklist item. This gate verifies continuity of Gate, Patrol, and qualified BASE coverage. Assess corrective coaching live or through a controlled role-play.</p>${promotionT4Form(['Shift-change handoff observed with open items and accurate times','Gate and BASE qualified relief verified','Routine decisions within Officer authority','Safety and access exceptions escalated promptly'])}<h3 class="pp-subheading">Corrective coaching practical</h3>${promotionEvaluationMethod()}${promotionGateExercise('T2-COACH')}${promotionT4Form(['Corrective coaching and development needs documented'])}${promotionT4FieldGrid(['Handoff date / shift','Supervisor evaluation / record reference'])}`);
}
function promotionLowerScenarios(p){
 const items=['Recognizes immediate safety and controls the scene','Uses the current procedure and verifies missing facts','Acts within the candidate tier authority','Communicates and escalates to qualified personnel','Updates decisions when new information arrives','Records facts, source and outcome accurately'];
 return `<div class="pp-section"><h2 class="pp-heading">Six verbal scenarios · evaluator record</h2><p class="pp-note">Keep this packet with the evaluator. Read the prompt aloud, let the candidate explain the sequence, then introduce the follow-up fact. Grade the actual spoken decisions, not memorized wording. A documented live or simulated scenario may satisfy a coaching or incident practical when evaluated to the same standard; verify actual signed post qualifications and historical work records separately. A critical safety, unauthorized access, falsified record or deliberate role-limit violation requires gate remediation or ineligibility review.</p>${p.scenarios.map((x,i)=>`<div class="pp-section"><h2 class="pp-heading">Scenario ${i+1} of 6 · ${esc(x.title||x.id||'')}</h2><p class="pp-small">Bank ID ${esc(x.id||'')} · ${esc(x.category||'General')} · Evaluator: ____________________ &nbsp; Date: __________</p><div class="pp-note"><b>Candidate prompt (read aloud):</b> ${esc(x.prompt||'').replace(/\n/g,'<br>')}</div>${x.inject?`<div class="pp-note"><b>Evaluator follow-up after initial answer:</b> ${esc(x.inject)}</div>`:'<p>Evaluator follow-up asked: _____________________________________________________________________</p>'}${promotionT4Form(items)}<div class="pp-sign">Candidate's verbal decision sequence and specific facts stated:</div><div class="pp-sign">Response to new information, authority and escalation assessment:</div><div class="pp-sign">Omissions, critical concern, coaching and recheck:</div><p><b>Evaluator grade:</b> □ MEETS □ COACHING □ REMEDIATE &nbsp; Critical failure: □ Yes □ No &nbsp; Signature: __________________</p></div>`).join('')}</div>`;
}

function promotionLowerSupervisor(p){
 return `<div class="pp-section"><h2 class="pp-heading">Supervisor evidence review and recommendation</h2><p>Verify every gate, all six spoken scenarios, live or simulated practical evidence, actual work history, and signed source records. Do not recommend promotion while a required gate has an unresolved critical failure.</p>${promotionT4Form(promotionGateNamesFor(p.tier).map((name,i)=>`Gate ${i+1} · ${name}`),'PASS / REMEDIATE / HOLD')}<h3 class="pp-subheading">Six oral scenario results</h3>${promotionT4Form((p.scenarios||[]).map((x,i)=>`Scenario ${i+1} · ${x.title||x.id}`),'MEETS / COACHING / REMEDIATE')}<div class="pp-sign">Specific observed strengths, dates and record sources:</div><div class="pp-sign">Gaps, corrective coaching and required reevaluation:</div><p>Recommendation: □ PROMOTE □ RETURN FOR DEVELOPMENT □ HOLD FOR MISSING EVIDENCE</p>${promotionT4FieldGrid(['Lead evaluator signature / date','Security Supervisor signature / date','Candidate acknowledgment of receipt only','Completed paper / scan location'])}</div>`;
}

function promotionLowerDecision(p){
 const names=promotionGateNamesFor(p.tier);
 const records=p.tier==='T1-T2'?['90-day probation and attendance reviewed','OJT-001 and four PMC-T1 records signed','Supervised Gate practical observed','Supervised Patrol practical observed','BASE awareness / EAP practical recorded','Professional pass-down and record integrity checked','Six verbal scenarios graded and signed','Supervisor recommendation and Manager decision signed']:
 ['PMC-Officer v2.0 and post qualifications signed','60-day documentation audit at least 98%','Sixty-day solo patrol evidence and disciplinary eligibility','Independent Gate practical and pass sample','Independent Patrol practical and log sample','Independent BASE practical and bookmark sample','Incident report and current EAP review','Handoff, six oral scenarios and Supervisor recommendation','Security Manager final decision and personnel filing'];
 return `<div class="pp-section"><h2 class="pp-heading">Security Manager final decision</h2><p>Verify each evidence gate separately. All gates must PASS for approval. Document gaps and give a controlled reevaluation path. The supervisor's recommendation does not independently change rank, compensation or HR status.</p><table><thead><tr><th>Gate</th><th>Status</th><th>Evidence checked / initials</th></tr></thead><tbody>${names.map((x,i)=>`<tr><td>Gate ${i+1} · ${esc(x)}</td><td>□ PASS □ REMEDIATE □ HOLD □ NOT ELIGIBLE</td><td>____________</td></tr>`).join('')}</tbody></table><p>□ All ${names.length} gates PASS &nbsp; □ Signed training and eligibility verified &nbsp; □ Six evaluator scenario records reviewed &nbsp; □ HR follow-up identified</p><p><b>Decision:</b> □ APPROVE PROMOTION □ DEFER / EXTEND REVIEW □ REMEDIATE AND REEVALUATE □ NOT CURRENTLY ELIGIBLE</p><div class="pp-sign">Manager decision rationale and specific evidence:</div>${promotionT4FieldGrid(['Security Manager signature / date','Effective date if separately processed','Controlled scan / original location','HR acknowledgment or follow-up'])}<p class="pp-small">This signed workbook is the Security Manager's approval record. Process roster rank, compensation and corporate HR changes under the applicable policy.</p></div><div class="pp-section"><h2 class="pp-heading">Evidence extension and reevaluation plan</h2>${promotionT4FieldGrid(['Gate(s) requiring evidence / remediation','Review window / extension date','Plan owner and authorized evaluator','Reevaluation date'])}${promotionT4Form(['Specific failed or missing evidence','Required standard and corrective coaching','Live or simulated coaching / incident recheck; signed source where required','Reevaluation result and Manager determination'])}<div class="pp-sign">Candidate factual correction and supporting source (if submitted):</div><div class="pp-sign">Security Manager disposition, date and signature:</div></div><div class="pp-section"><h2 class="pp-heading">Package completion checklist</h2>${records.map(x=>`<div class="pp-check">□ ${esc(x)} &nbsp; <span class="pp-small">Source / date: _______________________</span></div>`).join('')}<div class="pp-footer">PWADC Security · Packet ${esc(p.id)} · v5.5.0 · Confidential promotion record; file the signed original or controlled scan in the authorized personnel record.</div></div>`;
}
const promotionT4GateNames=["BASE station proficiency","Disciplinary eligibility","Attendance and reliability","Mentorship and FTO readiness","Operational judgment and leadership","Report writing and report review","Emergency response and incident coordination","Conduct and leadership character"];
function promotionT4Form(rows,decision='MEETS / COACHING / REMEDIATE'){
  return `<table><thead><tr><th style="width:45%">Evidence item / competency</th><th style="width:25%">Result · ${esc(decision)}</th><th>Specific evidence, source, date</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x)}</td><td>_________________</td><td style="height:36px"></td></tr>`).join('')}</tbody></table>`;
}

function promotionT4FieldGrid(labels){
  return `<div class="pp-grid">${labels.map(x=>`<div class="pp-field"><b>${esc(x)}</b><br>&nbsp;</div>`).join('')}</div>`;
}

function promotionT4Gate(n,body,closing='PASS / REMEDIATE'){
  return `<div class="pp-section"><h2 class="pp-heading">Gate ${n} · ${esc(promotionT4GateNames[n-1])}</h2>${body}<div class="pp-note">Gate ${n} final determination: ${esc(closing)} · Evidence reviewer: __________________ Date: __________<br>Deficiency / required reevaluation: _______________________________________________________________________</div></div>`;
}

function promotionT4Gates(p){
  const base=['Camera monitoring and situational awareness','Camera navigation and incident tracking','Forensic review and evidence identification','Radio dispatch and priority traffic management','Access control and Gate support judgment','Fire, ammonia and critical alarm recognition','Phone and intercom management under workload','BASE log accuracy and chronology','Multitasking and competing-priority control','Escalation judgment'];
  const practical=[1,2].map(n=>`<h3 class="pp-subheading">BASE practical evaluation ${n} · different date or shift</h3>${promotionEvaluationMethod()}${promotionGateExercise('T4-BASE'+n)}${promotionT4FieldGrid(['Shift','Manager conducted or directly reviewed?'])}${promotionT4Form(base)}<p>Critical failure: □ Yes □ No &nbsp; Result: □ PASS □ REMEDIATE &nbsp; Evaluator signature: ___________________</p>`).join('');
  const gate1=promotionT4Gate(1,`<p>Two successful practicals on different dates or shifts are required. At least one must be conducted or directly reviewed by the Security Manager. A critical safety, access, emergency, or judgment failure requires remediation.</p>${practical}${promotionT4Form(['Both practicals passed on separate dates or shifts','One practical conducted or directly reviewed by Security Manager','Any critical failure identified and remediated'],'YES / NO')}`);
  const gate2=promotionT4Gate(2,`<p>Review authorized personnel records privately. Record the source and any administrative hold.</p>${promotionT4Form(['Active Step 2 Written Warning or higher','Active Step 1 Verbal Warning and disclosure for review','Pending matter affecting leadership suitability','Administrative hold required','Required post-discipline satisfactory period completed'],'YES / NO / N/A')}${promotionT4FieldGrid(['Reviewed by','Review date','Manager eligibility determination'])}`,'PASS / HOLD / NOT ELIGIBLE');
  const gate3=promotionT4Gate(3,`<p>Document the rolling 90-day attendance pattern, 180-day NCNS and post abandonment history, and ordinary violations in the review window.</p>${promotionT4Form(['Rolling 90-day attendance pattern clear','NCNS during preceding 180 days','Unauthorized post abandonment during preceding 180 days','Ordinary attendance violations during 60-day review (0 / 1 / 2+)','Post-ready at shift start','Assignments completed without repeated follow-up','Coverage issues communicated in advance','Supervisor reliability assessment'],'YES / NO / COUNT')}${promotionT4FieldGrid(['Attendance window','Reviewer and date','Remediation period, if required'])}`);
  const gate4=promotionT4Gate(4,`<p>Evaluate coaching with a real trainee or a controlled role-play, using an independent verifier and the same competency standard. A simulation does not establish actual trainee solo proficiency.</p>${promotionEvaluationMethod()}${promotionGateExercise('T4-COACH')}${promotionT4FieldGrid(['Trainee / role-play participant','Post / competency','Independent verifier','Actual trainee record, if applicable'])}${promotionT4Form(['Explains purpose and standard','Demonstrates task correctly','Observes trainee performance','Identifies material deficiencies','Provides clear corrective coaching','Reevaluates corrected performance','Withholds signoff when standard is not met','Documents and escalates training gaps','Trainee reached solo proficiency (actual trainee only; N/A for simulation)','Outcome independently verified','Candidate was not sole evidence of own success'])}<h3 class="pp-subheading">Coaching assessment · live or simulated</h3>${promotionT4Form(['Knowledge of current procedure','Clarity and professionalism','Correct deficiency identified','Corrected performance independently verified','Documentation and follow-through','Simulation or alternative evaluation documented, if used'])}`);
  const observation=n=>`<h3 class="pp-subheading">Leadership observation ${n}</h3>${promotionEvaluationMethod()}${promotionGateExercise('T4-LEAD'+n)}${promotionT4FieldGrid(['Category: access / coverage / safety','Shift / context'])}<div class="pp-sign">Situation and presented facts:</div><div class="pp-sign">Candidate decision and action:</div><div class="pp-sign">Procedure and authority basis; escalation and outcome:</div><div>Escalation: □ Appropriate □ Unnecessary □ Failed &nbsp; Outcome: □ Effective □ Coached □ Reversed</div>`;
  const gate5=promotionT4Gate(5,`<p>Record at least three evaluated leadership decisions from live operations or controlled simulations, preferably spanning access/security, personnel/coverage, and safety/incident escalation. Review the actual 60-day judgment pattern separately.</p>${[1,2,3].map(observation).join('')}<h3 class="pp-subheading">Leadership practical and 60-day pattern</h3>${promotionT4Form(['Prioritization','Authority awareness','Decision quality','Communication and command presence','Escalation and documentation','Fairness and professional boundaries','Sixty-day judgment pattern'])}<p>Leadership scenario IDs: __________ &nbsp; Critical judgment failure: □ Yes □ No</p>`);
  const gate6=promotionT4Gate(6,`<p>Review three candidate authored reports and three shadow report reviews using actual incidents or controlled simulated cases; identify the method and case IDs for each. Complete the provided formal flawed report exercise below or an authorized case from the separate restricted evaluator bank. Identify material operational failures even in a well-written report.</p><h3 class="pp-subheading">Candidate authored report audit</h3>${promotionEvaluationMethod()}${[1,2,3].map(n=>promotionGateExercise('T4-REPORT'+n)).join('')}${promotionT4Form(['Report 1 · live/simulated, case ID, completeness / chronology / source / routing','Report 2 · live/simulated, case ID, conclusions / notification / escalation','Report 3 · live/simulated, case ID, improvement and follow-through'])}<h3 class="pp-subheading">Three shadow report reviews</h3>${promotionEvaluationMethod()}${[1,2,3].map(n=>promotionGateExercise('T4-SHADOW'+n)).join('')}${promotionT4Form(['Shadow review 1 · live/simulated, case ID, decision, issues, comparison','Shadow review 2 · live/simulated, case ID, decision, issues, comparison','Shadow review 3 · live/simulated, case ID, decision, issues, comparison'])}<h3 class="pp-subheading">Formal flawed report practical</h3>${promotionGateExercise('T4-FLAWED')}${promotionT4FieldGrid(['Exercise ID(s) R-01 to R-06','Evaluator / date'])}${promotionT4Form(['Identifies factual gaps and timeline defects','Separates firsthand facts, statements and opinion','Identifies unsupported medical or causation conclusions','Finds omitted notifications, parties and security failures','Selects Accept / Return / Escalate appropriately','Returns corrections without rewriting facts'])}<p>Critical report review failure: □ Yes □ No &nbsp; Practical: □ MEETS □ COACHING □ REMEDIATE</p>`);
  const gate7=promotionT4Gate(7,`<p>Check expected response against the current controlled EAP immediately before the practical. Three of the six verbal scenarios assess simulated emergency coordination; record their IDs, evaluator, date and results on the scenario pages. A live incident may also be assessed against the same standard.</p>${promotionT4Form(['Current controlled EAP reviewed','Security emergency role and authority boundaries understood','Superseded legacy procedures excluded','Emergency recognition and reassessment','Life-safety prioritization','Radio control and resource coordination','Hazard boundary and evacuation accountability','Responder access and handoff','Documentation and incident timeline'])}${promotionT4FieldGrid(['Three emergency scenario IDs','Evaluator / date','Critical failure? YES / NO'])}`);
  const gate8=promotionT4Gate(8,`<p>Use specific behavior from the 60-day review. Ask 360 sources for personally observed facts, dates and role only; do not solicit votes about promotion.</p>${promotionT4Form(['Integrity and truthfulness','Accountability','Emotional control and professional command presence','Fair and impartial treatment','Confidentiality and information control','Acceptance of corrective feedback','Professional boundaries and chain of command','Ability to disagree professionally'])}<h3 class="pp-subheading">Targeted factual 360 input</h3>${promotionT4Form(['Source / role 1 · observed event, approximate date, relevant domain','Source / role 2 · observed event, approximate date, relevant domain','Source / role 3 · observed event, approximate date, relevant domain'])}<p>Disqualifying leadership concern: □ Yes □ No &nbsp; Conduct: □ MEETS □ NEEDS DEVELOPMENT □ DISQUALIFYING</p>`,'PASS / REMEDIATE / NOT ELIGIBLE');
  const initiation=`<div class="pp-section"><h2 class="pp-heading">A · Review initiation and evidence control</h2><p>CONFIDENTIAL promotion evaluation. Record specific observed behavior rather than impressions. All eight gates are required; do not average a critical weakness against an unrelated strength. Do not sign a competency you did not observe or independently verify.</p>${promotionT4FieldGrid(['T3 effective date','Review start / planned end','Primary Security Supervisor','Lead evaluator(s)'])}${promotionT4Form(['Current T3 classification verified','Current post qualifications verified','Candidate promotion guide provided','Eight-gate standard explained','Known development priorities recorded','Review opened by Security Manager'],'YES / NO / HOLD')}<div class="pp-note">The source workbook and restricted scenario bank are v1.1 controlled drafts. Verify their current approved status and the current EAP before administering this packet. Keep evaluator keys separate from candidate materials.</div></div>`;
  return initiation+gate1+gate2+gate3+gate4+gate5+gate6+gate7+gate8;
}
function promotionT4Scenarios(p){
 const dimensions=['Prioritization','Authority awareness','Decision quality','Communication / command presence','Escalation and documentation','Reassessment when facts change'];
 return `<div class="pp-section"><h2 class="pp-heading">Six verbal scenarios · evaluator record</h2><div class="pp-note"><b>Controlled evaluator material.</b> Ask the candidate each prompt aloud and record their verbal response. Use the separate RESTRICTED Evaluator Scenario Bank v1.1 for injects, expected decisions, red flags and critical failure conditions; never hand that bank or its answer key to the candidate. Check emergency expectations against the current EAP. Do not score exact wording. Three leadership and three emergency scenarios were randomly selected at issue and remain fixed on reprint.</div>${p.scenarios.map((x,i)=>`<div class="pp-section"><h2 class="pp-heading">Scenario ${i+1} of 6 · ${esc(x.id||'')}</h2><p class="pp-small">${esc(x.category==='emergency'?'Emergency incident coordination':'Operational judgment and leadership')} · ${esc(x.title||'')} · Question date: __________ &nbsp; Evaluator: __________________</p><div class="pp-note"><b>Ask aloud:</b> ${esc(x.prompt||'')}</div><p class="pp-small">Restricted bank inject administered: ___________________ &nbsp; Candidate response changed with new facts? □ Yes □ No</p>${promotionT4Form(dimensions,'MEETS / COACHING / REMEDIATE')}<div class="pp-sign">What the candidate actually said; decision sequence and role limits:</div><div class="pp-sign">Follow-up / response to inject; observed strengths and gaps:</div><div class="pp-sign">Critical miss and evidence; required coaching or recheck:</div><p><b>Evaluator grade:</b> □ MEETS □ COACHING □ REMEDIATE &nbsp; Critical failure: □ Yes □ No &nbsp; Evaluator signature: __________________</p></div>`).join('')}</div>`;
}

function promotionT4Supervisor(p){
 return `<div class="pp-section"><h2 class="pp-heading">C · Supervisor final recommendation</h2><p>Enter each gate status from the signed evidence above. A scenario score cannot cancel a critical failure. Document live or simulated coaching and incident evaluations; independently verify signed qualifications and historical conduct. Give a clear reason for any remediation or ineligibility.</p>${promotionT4Form(promotionT4GateNames.map((x,i)=>`Gate ${i+1} · ${x}`),'PASS / REMEDIATE / HOLD')}<div class="pp-sign">Specific observed strengths and sources:</div><div class="pp-sign">Unresolved gaps, coaching given, and dated rechecks:</div><p>Recommendation: □ PROMOTE □ DO NOT PROMOTE □ REMEDIATE</p>${promotionT4FieldGrid(['Security Supervisor signature / date','Evaluator signature / date','Signed original / scan reference'])}</div>`;
}

function promotionT4Interview(p){
 const questions=['What changes when you become a Lead Officer?','What is the biggest mistake a new Lead can make?','How do you prevent friendship from affecting assignments or evaluations?','Describe one decision in this review you would handle differently now.','When should a Lead explain a decision, and when must the shift move forward?','When should a Lead involve the Supervisor instead of resolving the issue?','When would you withhold a training signoff from an officer you like?','What does Acting Supervisor authority mean and how is it activated?','If promoted tomorrow, what part of the Lead role still needs development?'];
 return `<div class="pp-section"><h2 class="pp-heading">B · Security Manager final candidate interview</h2><p>Conduct a 20–30 minute leadership readiness discussion. Ask for real decisions and document evidence; this is not another policy quiz.</p>${questions.map((x,i)=>`<div class="pp-check"><b>${i+1}. ${esc(x)}</b><div class="pp-line"></div><div class="pp-line"></div></div>`).join('')}<p>Interview outcome: □ Meets standard □ Needs development &nbsp; Date: __________</p><div class="pp-sign">Manager assessment and follow-up:</div>${promotionT4FieldGrid(['Security Manager signature','Interview date'])}</div>`;
}

function promotionT4Decision(p){
 const gateStatus=promotionT4GateNames.map((x,i)=>`<tr><td>Gate ${i+1} · ${esc(x)}</td><td>□ PASS □ REMEDIATE □ HOLD □ NOT ELIGIBLE</td><td>__________</td></tr>`).join('');
 const completion=['Review initiation and eligibility','Two BASE practicals on different dates / Manager verification','Disciplinary eligibility and attendance review','Mentorship or authorized FTO alternative','Three leadership observations and practical','Candidate report audit, three shadow reviews, flawed report practical','Current EAP review and three emergency scenarios','Conduct assessment and factual 360 input','Six verbal scenario grades and evaluator notes','Final Security Manager interview','Supervisor signed recommendation','Manager decision and HR follow-up','Candidate informed and signed record filed'];
 return `<div class="pp-section"><h2 class="pp-heading">D · Security Manager final determination</h2><p>Verify each gate separately. If a critical weakness remains, select remediation or ineligibility as appropriate. Approval requires all eight gates PASS and a dated Manager interview rated Meets standard.</p><table><thead><tr><th>Final gate</th><th>Status</th><th>Evidence checked / initials</th></tr></thead><tbody>${gateStatus}</tbody></table><p>□ All eight gates passed &nbsp; □ Package complete &nbsp; □ Final interview passed &nbsp; □ HR action checked: □ Complete □ Pending □ Not required</p><p><b>Decision:</b> □ PROMOTE □ EXTEND REVIEW □ REMEDIATE AND REEVALUATE □ NOT CURRENTLY ELIGIBLE</p><div class="pp-sign">Security Manager decision rationale, conditions, and source records:</div>${promotionT4FieldGrid(['Security Manager signature / date','Effective date if separately processed','HR acknowledgment / action','Controlled paper or scan reference'])}<p class="pp-small">This signed workbook is the promotion decision record; roster, compensation and HR actions follow the applicable policy.</p></div><div class="pp-section"><h2 class="pp-heading">E · Extension, remediation and factual correction</h2><h3 class="pp-subheading">Review extension · normally no more than 30 days</h3>${promotionT4FieldGrid(['Original end date','Extension start / end','Authorized by','Evidence still required'])}<p>An extension addresses missing evidence; it does not turn a failed gate into a pass. Document any exceptional second extension.</p><h3 class="pp-subheading">Remediation and reevaluation plan</h3>${promotionT4Form(['Gate(s) and specific deficiency','Required standard and development action','Evidence needed and evaluator','Reevaluation result / Manager disposition'])}<h3 class="pp-subheading">Candidate factual correction request</h3><p>Identify a claimed factual inaccuracy and its supporting source. Professional evaluator judgment is assessed separately.</p>${promotionT4FieldGrid(['Statement contested','Candidate correction and evidence','Manager disposition / date'])}</div><div class="pp-section"><h2 class="pp-heading">H · Package completion checklist</h2>${completion.map(x=>`<div class="pp-check">□ ${esc(x)} &nbsp; <span class="pp-small">Reference / date: _______________________</span></div>`).join('')}<div class="pp-footer">PWADC Security · Packet ${esc(p.id)} · v5.5.0 · Confidential promotion record; store the signed original or controlled scan in the authorized personnel location. Source workbook v1.1 remains a controlled draft until issued.</div></div>`;
}
function printPromotionRegister(){
  const rows=(promotionPackets.packets||[]).filter(p=>p.status!=='Deleted');
  const body=`<div class="print-header"><div><div class="print-brand">PWADC Security</div><h1>Promotion Packet Register</h1></div><div class="print-meta">${esc(new Date().toLocaleString())}</div></div>${reportTable(['Candidate','Level','Issued','Status','Supervisor recommendation','Manager decision','Packet ID'],rows.map(p=>[esc(p.employee?.name||''),esc(p.tier||''),esc(promotionLocalDate(p.issuedAt)),esc(p.status||''),esc(p.review?.recommendation||''),esc(p.decision?.result||''),esc(p.id||'')]))}`;
  printHtmlDirect('PWADC Promotion Packet Register',body,'landscape');
}
function exportPromotionRegister(){
  downloadCSV('PWADC_Promotion_Packets_'+facilityToday()+'.csv',[['Candidate','EID','Level','Issued','Status','Supervisor recommendation','Manager decision','Packet ID'],...(promotionPackets.packets||[]).filter(p=>p.status!=='Deleted').map(p=>[p.employee?.name||'',p.employee?.eid||'',p.tier||'',p.issuedAt||'',p.status||'',p.review?.recommendation||'',p.decision?.result||'',p.id||''])]);
}
PWADCModuleRegistry.register('promotion-packets');
